import hashlib
import hmac
import os

def register_device(device_id: str, pin: str) -> dict[str, str]:
    device_id = device_id.strip()
    if not device_id or len(pin) != 4 or (not all(('0' <= char <= '9' for char in pin))):
        raise ValueError('invalid device registration')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'device_id': device_id, 'pin_hash': salt.hex() + ':' + digest.hex()}

def authenticate_device(record: dict[str, str], pin: str) -> bool:
    try:
        encoded = record['pin_hash']
        salt_text, digest_text = encoded.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

