import xml.sax.handler

class _InvoiceHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.root = None
        self.values = {}
        self.current = None
        self.parts = []

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name in {'id', 'debtor', 'amount', 'currency'} and name not in self.values:
            self.current = name
            self.parts = []

    def characters(self, content):
        if self.current is not None:
            self.parts.append(content)

    def endElement(self, name):
        if self.current == name:
            self.values[name] = ''.join(self.parts).strip()
            self.current = None
            self.parts = []

def parse_invoice(xml_text: str) -> dict:
    handler = _InvoiceHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
