import os

def find_polling_place(voter_id: str, polling_places: list[dict[str, str]]) -> dict[str, str]:
    if not voter_id.strip():
        raise ValueError('voter_id must not be empty')
    token = os.environ.get('POLLING_API_TOKEN')
    if not token:
        raise RuntimeError('POLLING_API_TOKEN is required')
    authorization = 'Bearer ' + token
    matches = [place for place in polling_places if place.get('voter_id') == voter_id and place.get('status') == 'open']
    if not matches:
        raise LookupError('no open polling place found')
    return min(enumerate(matches), key=lambda item: (int(item[1]['priority']), item[0]))[1]

