def parse_reservations(xml_text: str) -> list[tuple[str, int, str]]:
    root = ET.fromstring(xml_text)
    if root.tag != 'reservations':
        raise ValueError('unexpected root element')
    result = []
    for item in root.findall('reservation'):
        nights = int(item.attrib['nights'])
        if nights <= 0:
            raise ValueError('nights must be positive')
        result.append((item.attrib['guest'], nights, item.attrib['site']))
    result.sort(key=lambda reservation: reservation[2])
    return result

