    if not isinstance(signature, str) or not signature.startswith('sha256='):
        return None
    provided = signature[7:]
    if len(provided) != 64 or any((c not in '0123456789abcdef' for c in provided)):
        return None
    expected = hmac.new(key, body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(provided, expected):
        return None
    return payload

