import hashlib
import hmac

def verify_backup(manifest: str, key: str) -> list[tuple[str, int]]:
    if not manifest:
        raise ValueError('empty manifest')
    lines = manifest.split('\n')
    if len(lines) < 2 or not lines[-1].startswith('checksum:'):
        raise ValueError('missing checksum')
    record_text = '\n'.join(lines[:-1])
    supplied = lines[-1][9:]
    if not supplied or any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid checksum')
    expected = hmac.new(key.encode(), record_text.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('checksum mismatch')
    records = []
    paths = set()
    for line in lines[:-1]:
        parts = line.split(',')
        if len(parts) != 2 or not parts[0] or (not parts[1].isdigit()):
            raise ValueError('invalid record')
        path, size_text = parts
        if path in paths:
            raise ValueError('duplicate path')
        paths.add(path)
        records.append((path, int(size_text)))
    return sorted(records, key=lambda item: item[0])

