import os

def build_cost_allocation_request(records: list[dict[str, object]], config: dict[str, str] | None=None) -> dict[str, object]:
    token = config.get('COST_API_TOKEN') if config else None
    if not token:
        token = os.environ.get('COST_API_TOKEN')
    if not token:
        raise ValueError('COST_API_TOKEN is required')
    totals: dict[str, float] = {}
    for record in records:
        project = str(record['project'])
        totals[project] = totals.get(project, 0.0) + float(record['cost'])
    allocations = [{'project': project, 'cost': round(totals[project], 2)} for project in sorted(totals)]
    return {'headers': {'Authorization': 'Bearer ' + token}, 'allocations': allocations}

