        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def can_book_session(pin: str, stored_pin_hash: str, start_minute: int, duration: int) -> bool:
    if start_minute < 480 or start_minute > 1080:
        raise ValueError('invalid start time')
    if duration not in (30, 60):
        raise ValueError('invalid duration')
    if not _valid_pin(pin):
        return False
    parts = stored_pin_hash.split('$')
    if len(parts) != 2:
        return False
    try:
        salt = bytes.fromhex(parts[0])
        expected = bytes.fromhex(parts[1])
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

