import operator

def filter_exercises(exercises: list[dict[str, float]], rule: str) -> list[dict[str, float]]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except (SyntaxError, ValueError, TypeError) as exc:
        raise ValueError('invalid rule') from exc
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    comparisons = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, values)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = evaluate(node.values[0], values)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And):
                    if not result:
                        return result
                elif result:
                    return result
                result = evaluate(item, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for operation, right_node in zip(node.ops, node.comparators):
                if type(operation) not in comparisons:
                    raise ValueError('invalid rule')
                right = evaluate(right_node, values)
                if not comparisons[type(operation)](left, right):
                    return False
                left = right
            return True
        raise ValueError('invalid rule')
    result = []
    for exercise in exercises:
        if evaluate(tree, exercise):
            result.append(exercise)
    return result

