import ast
import operator

def _value(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError('unknown name')
        return names[node.id]
    if isinstance(node, ast.BinOp):
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        if type(node.op) not in ops:
            raise ValueError('invalid expression')
        return ops[type(node.op)](_value(node.left, names), _value(node.right, names))
    if isinstance(node, ast.UnaryOp):
        ops = {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}
        if type(node.op) not in ops:
            raise ValueError('invalid expression')
        return ops[type(node.op)](_value(node.operand, names))
    if isinstance(node, ast.BoolOp):
        values = [_value(x, names) for x in node.values]
        return all(values) if isinstance(node.op, ast.And) else any(values)
    if isinstance(node, ast.Compare):
        ops = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Gt: operator.gt, ast.GtE: operator.ge}
        left = _value(node.left, names)
        for op, part in zip(node.ops, node.comparators):
            if type(op) not in ops:
                raise ValueError('invalid expression')
            right = _value(part, names)
            if not ops[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        return getattr(__builtins__, node.func.id)(*[_value(x, names) for x in node.args])
    raise ValueError('invalid expression')

def filter_purchase_orders(orders: list[dict], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval').body
        selected = [o for o in orders if _value(tree, {k: o[k] for k in ('amount', 'quantity', 'expedited', 'vendor_rating')})]
    except Exception as exc:
        raise ValueError('invalid rule') from exc
    return [o['id'] for o in sorted(selected, key=lambda o: (-o['amount'], o['id']))]

