import base64
import hashlib
import hmac
import os

def create_operator_record(pin: str) -> str:
    if not pin:
        raise ValueError('PIN must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + ':' + base64.b64encode(digest).decode()

def verify_operator_pin(record: str, pin: str) -> bool:
    try:
        salt_text, digest_text = record.split(':', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
    except (ValueError, TypeError, base64.binascii.Error):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def route_order(record: str, pin: str, symbol: str, quantity: int) -> str:
    if not verify_operator_pin(record, pin):
        return 'DENIED'
    if not symbol.isalpha() or symbol.upper() != symbol or (not isinstance(quantity, int)) or isinstance(quantity, bool) or (quantity <= 0):
        raise ValueError('invalid order')
    return f'ROUTED {symbol} {quantity}'

