    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in variables:
            raise NameError(node.id)
        return variables[node.id]
    if isinstance(node, ast.BinOp):
        left = _value(node.left, variables)
        right = _value(node.right, variables)
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        if type(node.op) not in ops:
            raise ValueError('invalid expression')
        return ops[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _value(node.operand, variables)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BoolOp):
        values = [_value(x, variables) for x in node.values]
        if isinstance(node.op, ast.And):
            return next((x for x in values if not x), values[-1])
        return next((x for x in values if x), values[-1])
    if isinstance(node, ast.Compare):
        current = _value(node.left, variables)
        for op, part in zip(node.ops, node.comparators):
            other = _value(part, variables)
            funcs = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}
            if type(op) not in funcs or not funcs[type(op)](current, other):
                return False
            current = other
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        args = [_value(x, variables) for x in node.args]
        if node.func.id == 'round' and len(args) not in (1, 2):
            raise ValueError('invalid expression')
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
    raise ValueError('invalid expression')

